package com.zerostreams.app;
import android.content.Intent;import android.webkit.WebView;import android.view.*;import androidx.test.core.app.ActivityScenario;import androidx.test.platform.app.InstrumentationRegistry;import androidx.test.ext.junit.runners.AndroidJUnit4;import org.junit.*;import org.junit.runner.RunWith;import org.json.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
@RunWith(AndroidJUnit4.class) public class SportsPlayerTest {
 WebView find(View view){if(view instanceof WebView)return(WebView)view;if(view instanceof ViewGroup){ViewGroup group=(ViewGroup)view;for(int i=0;i<group.getChildCount();i++){WebView result=find(group.getChildAt(i));if(result!=null)return result;}}return null;}
 String js(ActivityScenario<SportsPlayerActivity> scenario,String code)throws Exception{CountDownLatch latch=new CountDownLatch(1);AtomicReference<String> value=new AtomicReference<>();scenario.onActivity(a->find(a.getWindow().getDecorView()).evaluateJavascript(code,r->{value.set(r);latch.countDown();}));Assert.assertTrue(latch.await(8,TimeUnit.SECONDS));return value.get();}
 @Test public void htmlPlayerKeepsScriptsAdsAndAlternateSources()throws Exception{JSONArray sources=new JSONArray().put(new JSONObject().put("source_tag","Main fixture").put("iframe","<div id='ad'>Provider advertisement</div><button id='control' onclick=\"document.body.dataset.clicked='yes'\">Play fixture</button><script>localStorage.setItem('sports-fixture','kept');document.body.dataset.ready='yes'</script>")).put(new JSONObject().put("source_tag","Alternative fixture").put("iframe","<div id='alternate'>Alternate loaded</div>"));Intent intent=new Intent(InstrumentationRegistry.getInstrumentation().getTargetContext(),SportsPlayerActivity.class).putExtra("sources",sources.toString()).putExtra("base","https://api.ppv.st");try(ActivityScenario<SportsPlayerActivity> scenario=ActivityScenario.launch(intent)){String ready="";for(int i=0;i<40;i++){ready=js(scenario,"document.body.dataset.ready");if("\"yes\"".equals(ready))break;Thread.sleep(100);}Assert.assertEquals("\"yes\"",ready);Assert.assertEquals("\"Provider advertisement\"",js(scenario,"document.getElementById('ad').textContent"));Assert.assertEquals("\"kept\"",js(scenario,"localStorage.getItem('sports-fixture')"));Assert.assertEquals("\"undefined\"",js(scenario,"typeof window.__zeroBlockAds"));scenario.onActivity(a->{a.selected=1; a.load();});String alternative="";for(int i=0;i<40;i++){alternative=js(scenario,"document.getElementById('alternate')?.textContent");if("\"Alternate loaded\"".equals(alternative))break;Thread.sleep(100);}Assert.assertEquals("\"Alternate loaded\"",alternative);scenario.onActivity(a->{a.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_DOWN,KeyEvent.KEYCODE_DPAD_RIGHT));a.dispatchKeyEvent(new KeyEvent(KeyEvent.ACTION_UP,KeyEvent.KEYCODE_DPAD_RIGHT));a.onBackPressed();});}}
}
